@pytest.mark.e2e
async def test_journal_balanced_entry_creation_and_post(page: Page):
    'AC-ledger.journal-entry.1 AC-ledger.journal-entry.2 EPIC-001 EPIC-008'; runner = ScenarioBenchmarkRunner(base_url=APP_URL, timeout=120.0); client, _user_email, _ = runner.create_ephemeral_client('journal_create'); runner.create_account(client, name='Operating Cash', type='ASSET', currency='SGD'); runner.create_account(client, name='Owner Capital', type='EQUITY', currency='SGD'); assert runner.last_auth_context is not None; await BenchUiBridge.inject_runner_session_to_browser(page, runner.last_auth_context, APP_URL); await page.goto(f'{APP_URL}/journal', wait_until='domcontentloaded'); await expect(page.get_by_role('heading', name='Journal Entries', exact=True)).to_be_visible(timeout=15000); await page.get_by_role('button', name='New Entry').click(); await expect(page.get_by_role('heading', name='New Journal Entry', exact=True)).to_be_visible(timeout=10000); memo_text = 'Balanced Capital Injection'; await page.locator('input[placeholder="Description"]').fill(memo_text); await page.locator('input[placeholder="Why this entry is correct"]').fill('Owner initial contribution'); line1_account = page.get_by_role('combobox', name='Line 1 account'); await expect(line1_account).to_be_visible(); await line1_account.select_option(label='Operating Cash'); await page.get_by_role('spinbutton', name='Line 1 amount').fill('500.00'); line2_account = page.get_by_role('combobox', name='Line 2 account'); await line2_account.select_option(label='Owner Capital'); await page.get_by_role('spinbutton', name='Line 2 amount').fill('500.00'); await page.locator('#postImmediately').check(); await expect(page.get_by_text('✓ Balanced in SGD')).to_be_visible(); submit_btn = page.get_by_role('button', name='Create & Post'); await expect(submit_btn).to_be_enabled(); calls: list[str] = []
    async def _record(response) -> None:
        if '/api/' in response.url and response.request.method != 'GET':
            try: body = (await response.text())[:200]
            except Exception as exc: body = f'<{type(exc).__name__}>'
            calls.append(f'{response.request.method} {response.url} -> {response.status} {body}')
    page.on('response', lambda response: asyncio.ensure_future(_record(response))); await submit_btn.click()
    try: await expect(page.get_by_role('heading', name='New Journal Entry', exact=True)).not_to_be_visible(timeout=MODAL_CLOSE_TIMEOUT_MS)
    except AssertionError as exc: alerts = await page.locator('[role="alert"], [role="status"]').all_inner_texts(); raise AssertionError(f'The journal modal stayed open for {MODAL_CLOSE_TIMEOUT_MS} ms. API calls: {calls}. Alerts: {alerts}') from exc
    await expect(page.get_by_text(memo_text)).to_be_visible(timeout=15000)
